sys_script.script:
(function executeRule(current, previous /*, gs */) {
    // Guard closure: block the transition into 'closed' when mandatory tasks are
    // incomplete or a resolution code/summary is missing.
    if (current.getValue('case_status') !== 'closed') {
        return;
    }
    // Only enforce on the actual transition into 'closed'.
    if (previous && previous.getValue('case_status') === 'closed') {
        return;
    }

    var utils = new bfd_CaseUtils();
    var reasons = [];
    if (current.getValue('resolution_code') === '' || current.getValue('resolution_code') === null) {
        reasons.push('a resolution code is required');
    }
    if (current.getValue('resolution_summary') === '' || current.getValue('resolution_summary') === null) {
        reasons.push('a resolution summary is required');
    }
    if (!utils.mandatoryTasksComplete(current)) {
        reasons.push('all mandatory tasks (identity verification, transaction review, approval) must be complete');
    }

    if (reasons.length) {
        gs.addErrorMessage('Cannot close this case: ' + reasons.join('; ') + '.');
        current.setAbortAction(true);
    }
})(current, previous);
